pragma solidity ^0.4.19;

contract BANK_SAFE
{
mapping (address=>uint256) public balances;

uint public MinSum;

LogFile Log;

bool intitalized;

function SetMinSum(uint _val)
public
{
if(intitalized)throw;
MinSum = _val;
}

function SetLogFile(address _log)
public
{
if(intitalized)throw;
Log = LogFile(_log);
}

function Initialized()
public
{
intitalized = true;
}

function Deposit()
public
payable
{
balances[msg.sender]+= msg.value;
